cat > internal/ext/exporter.go <<'"'EOF'
package ext

import (
 \"context\"
 \"encoding/json\"
 \"fmt\"
 \"io\"

 flipt \"github.com/markphelps/flipt/rpc/flipt\"
 \"github.com/markphelps/flipt/storage\"
 \"gopkg.in/yaml.v2\"
)

type lister interface {
 ListFlags(context.Context, ...storage.QueryOption) ([]*flipt.Flag,error)
 ListRules(context.Context,string,...storage.QueryOption) ([]*flipt.Rule,error)
 ListSegments(context.Context,...storage.QueryOption) ([]*flipt.Segment,error)
}
type Exporter struct { store lister; batchSize uint64 }
func NewExporter(store lister) *Exporter { return &Exporter{store:store,batchSize:25} }
func (e *Exporter) Export(ctx context.Context,w io.Writer) error {
 doc:=new(Document)
 for offset:=uint64(0);;offset+=e.batchSize {
  flags,err:=e.store.ListFlags(ctx,storage.WithOffset(offset),storage.WithLimit(e.batchSize));if err"'!=nil{return fmt.Errorf("getting flags: %w",err)}
  for _,f:=range flags {
   flag:=&Flag{Key:f.Key,Name:f.Name,Description:f.Description,Enabled:f.Enabled}
   keys:=make(map[string]string)
   for _,v:=range f.Variants {
    variant:=&Variant{Key:v.Key,Name:v.Name,Description:v.Description}
    if v.Attachment!="" { if err:=json.Unmarshal([]byte(v.Attachment),&variant.Attachment);err!=nil{return fmt.Errorf("decoding attachment for variant %q: %w",v.Key,err)} }
    flag.Variants=append(flag.Variants,variant);keys[v.Id]=v.Key
   }
   rules,err:=e.store.ListRules(ctx,f.Key);if err!=nil{return fmt.Errorf("getting rules for flag %q: %w",f.Key,err)}
   for _,r:=range rules {rule:=&Rule{SegmentKey:r.SegmentKey,Rank:uint(r.Rank)};for _,d:=range r.Distributions {rule.Distributions=append(rule.Distributions,&Distribution{VariantKey:keys[d.VariantId],Rollout:d.Rollout})};flag.Rules=append(flag.Rules,rule)}
   doc.Flags=append(doc.Flags,flag)
  }
  if uint64(len(flags))<e.batchSize {break}
 }
 for offset:=uint64(0);;offset+=e.batchSize {
  segments,err:=e.store.ListSegments(ctx,storage.WithOffset(offset),storage.WithLimit(e.batchSize));if err!=nil{return fmt.Errorf("getting segments: %w",err)}
  for _,s:=range segments {segment:=&Segment{Key:s.Key,Name:s.Name,Description:s.Description};for _,c:=range s.Constraints {segment.Constraints=append(segment.Constraints,&Constraint{Type:c.Type.String(),Property:c.Property,Operator:c.Operator,Value:c.Value})};doc.Segments=append(doc.Segments,segment)}
  if uint64(len(segments))<e.batchSize {break}
 }
 enc:=yaml.NewEncoder(w);defer enc.Close()
 if err:=enc.Encode(doc);err!=nil{return fmt.Errorf("exporting: %w",err)}
 return nil
}
EOF
cat > internal/ext/importer.go <<'"'EOF'
package ext

import (
 \"context\"
 \"encoding/json\"
 \"fmt\"
 \"io\"

 flipt \"github.com/markphelps/flipt/rpc/flipt\"
 \"gopkg.in/yaml.v2\"
)

type creator interface {
 CreateFlag(context.Context,*flipt.CreateFlagRequest)(*flipt.Flag,error)
 CreateVariant(context.Context,*flipt.CreateVariantRequest)(*flipt.Variant,error)
 CreateSegment(context.Context,*flipt.CreateSegmentRequest)(*flipt.Segment,error)
 CreateConstraint(context.Context,*flipt.CreateConstraintRequest)(*flipt.Constraint,error)
 CreateRule(context.Context,*flipt.CreateRuleRequest)(*flipt.Rule,error)
 CreateDistribution(context.Context,*flipt.CreateDistributionRequest)(*flipt.Distribution,error)
}
type Importer struct {store creator}
func NewImporter(store creator)*Importer{return &Importer{store:store}}
// convert replaces YAML's interface-keyed maps recursively with string-keyed maps.
func convert(value interface{}) interface{} {
 switch v:=value.(type) {
 case map[interface{}]interface{}:
  result:=make(map[string]interface{},len(v));for key,item:=range v {result[fmt.Sprint(key)]=convert(item)};return result
 case map[string]interface{}:
  result:=make(map[string]interface{},len(v));for key,item:=range v {result[key]=convert(item)};return result
 case []interface{}:
  result:=make([]interface{},len(v));for i,item:=range v {result[i]=convert(item)};return result
 default:return value
 }
}
func (i *Importer) Import(ctx context.Context,r io.Reader)error {
 doc:=new(Document)
 if err:=yaml.NewDecoder(r).Decode(doc);err"'!=nil{return fmt.Errorf("importing: %w",err)}
 variants:=make(map[string]*flipt.Variant)
 for _,f:=range doc.Flags {
  if _,err:=i.store.CreateFlag(ctx,&flipt.CreateFlagRequest{Key:f.Key,Name:f.Name,Description:f.Description,Enabled:f.Enabled});err!=nil{return fmt.Errorf("importing flag: %w",err)}
  for _,v:=range f.Variants {
   attachment:=""
   if v.Attachment!=nil {data,err:=json.Marshal(convert(v.Attachment));if err!=nil{return fmt.Errorf("encoding attachment for variant %q: %w",v.Key,err)};attachment=string(data)}
   variant,err:=i.store.CreateVariant(ctx,&flipt.CreateVariantRequest{FlagKey:f.Key,Key:v.Key,Name:v.Name,Description:v.Description,Attachment:attachment});if err!=nil{return fmt.Errorf("importing variant: %w",err)}
   variants[f.Key+":"+v.Key]=variant
  }
 }
 for _,s:=range doc.Segments {
  if _,err:=i.store.CreateSegment(ctx,&flipt.CreateSegmentRequest{Key:s.Key,Name:s.Name,Description:s.Description});err!=nil{return fmt.Errorf("importing segment: %w",err)}
  for _,c:=range s.Constraints {if _,err:=i.store.CreateConstraint(ctx,&flipt.CreateConstraintRequest{SegmentKey:s.Key,Type:flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),Property:c.Property,Operator:c.Operator,Value:c.Value});err!=nil{return fmt.Errorf("importing constraint: %w",err)}}
 }
 for _,f:=range doc.Flags {for _,r:=range f.Rules {
  rule,err:=i.store.CreateRule(ctx,&flipt.CreateRuleRequest{FlagKey:f.Key,SegmentKey:r.SegmentKey,Rank:int32(r.Rank)});if err!=nil{return fmt.Errorf("importing rule: %w",err)}
  for _,d:=range r.Distributions {variant,ok:=variants[f.Key+":"+d.VariantKey];if !ok{return fmt.Errorf("finding variant: %s; flag: %s",d.VariantKey,f.Key)};if _,err:=i.store.CreateDistribution(ctx,&flipt.CreateDistributionRequest{FlagKey:f.Key,RuleId:rule.Id,VariantId:variant.Id,Rollout:d.Rollout});err!=nil{return fmt.Errorf("importing distribution: %w",err)}}
 }}
 return nil
}
EOF
